import java.io.BufferedReader;
import java.io.InputStreamReader;

public class bubblestrike {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] tokens = line.split(" ");
        int startX = Integer.parseInt(tokens[0]);
        double targetProbability = Double.parseDouble(tokens[1]);
        int position = startX;
        for (int stepSize = startX; stepSize > 0; stepSize /= 2) {
            while (position - stepSize >= 0 && check(position - stepSize, startX - (position - stepSize), targetProbability)) {
                position -= stepSize;
            }
        }
        System.out.println(position);
        br.close();
    }

    public static boolean check(int good, int bad, double p) {
        double g = good;
        double b = bad;
        double numerator = (0.25 * b * Math.max(0, b - 1) * g
                + (g * (Math.max(0, g - 1) * Math.max(0, g - 2) / 6.0) + b * 0.5 * g * Math.max(0, g - 1)));
        double denominator = (g + b) * Math.max(0, g + b - 1) * Math.max(0, g + b - 2) / 6.0;
        double ans = numerator / denominator;
        return ans >= p;
    }
}
